/* ── the player ───────────────────────────────────────────────────── */
function useStreamPlayer(scriptKey, runId) {
  const [phase, setPhase] = useState("thinking"); // thinking | streaming | done | stopped | error
  const [meta, setMeta] = useState(null);
  const [items, setItems] = useState([]); // ordered prose+block items
  const [errorMsg, setErrorMsg] = useState(null);
  const [slow, setSlow] = useState(false);
  const timers = useRef([]);
  const stopped = useRef(false);
  useEffect(() => {
    stopped.current = false;
    setPhase("thinking");
    setMeta(null);
    setItems([]);
    setErrorMsg(null);
    setSlow(false);
    const script = STREAM_SCRIPTS[scriptKey] || STREAM_SCRIPTS.normal;
    const T = [];
    let clock = 0;
    const at = (ms, fn) => {
      clock += ms;
      T.push(setTimeout(() => {
        if (!stopped.current) fn();
      }, clock));
    };
    at(900, () => setPhase("streaming")); // thinking shimmer before first token

    script.forEach(f => {
      if (f.t === "meta") {
        at(40, () => setMeta(f.meta));
      } else if (f.t === "token") {
        const words = f.text.split(" ");
        at(180, () => setItems(it => [...it, {
          kind: "prose",
          id: f.id,
          full: f.text,
          n: 0
        }]));
        words.forEach((_, wi) => at(34, () => setItems(it => it.map(x => x.id === f.id ? {
          ...x,
          n: wi + 1
        } : x))));
      } else if (f.t === "block-start") {
        at(160, () => setItems(it => [...it, {
          kind: "block",
          id: f.id,
          block: f.block,
          state: "loading",
          slow: f.slow
        }]));
        if (f.slow) at(20, () => setSlow(true));
      } else if (f.t === "block-data") {
        at(f.slow ? 1500 : 620, () => {
          setItems(it => it.map(x => x.id === f.id ? {
            ...x,
            state: "normal"
          } : x));
          setSlow(false);
        });
      } else if (f.t === "block-end") {/* no-op visual */} else if (f.t === "error") {
        at(900, () => {
          setItems(it => it.map(x => x.id === f.id ? {
            ...x,
            state: "error"
          } : x));
          setErrorMsg(f.message);
          setPhase("error");
        });
      } else if (f.t === "done") {
        at(420, () => setPhase("finalizing"));
        at(520, () => setPhase("done"));
      }
    });
    timers.current = T;
    return () => T.forEach(clearTimeout);
  }, [scriptKey, runId]);
  const stop = () => {
    stopped.current = true;
    timers.current.forEach(clearTimeout);
    setItems(it => it.map(x => x.kind === "block" && x.state === "loading" ? {
      ...x,
      state: "stopped"
    } : x));
    setPhase("stopped");
  };
  return {
    phase,
    meta,
    items,
    errorMsg,
    slow,
    stop
  };
}

