/* ── Price series (deterministic so it never jiggles on re-render) ── */
function genCandles(n, start, end) {
  const out = [];
  let p = start;
  const drift = (end - start) / n;
  for (let i = 0; i < n; i++) {
    const noise = (Math.sin(i * 0.7) + Math.cos(i * 1.31) + Math.sin(i * 2.2) * 0.5) * (start * 0.006);
    const o = p,
      c = o + drift + noise;
    const wick = (Math.abs(Math.sin(i * 1.9)) + 0.3) * start * 0.004;
    const h = Math.max(o, c) + wick,
      l = Math.min(o, c) - wick;
    const v = Math.round(2.0e6 + Math.abs(noise) / (start * 0.006) * 1.4e6 + Math.abs(Math.sin(i * 0.9)) * 1.1e6);
    out.push({
      o: +o.toFixed(1),
      h: +h.toFixed(1),
      l: +l.toFixed(1),
      c: +c.toFixed(1),
      v
    });
    p = c;
  }
  return out;
}
function trailingMA(series, w) {
  return series.map((_, i) => {
    const s = Math.max(0, i - w + 1),
      sl = series.slice(s, i + 1);
    return +(sl.reduce((a, b) => a + b.c, 0) / sl.length).toFixed(1);
  });
}
